function nz(string $s):string{$s=strtr($s,['ي'=>'ی','ى'=>'ی','ك'=>'ک','ة'=>'ه','ۀ'=>'ه','ؤ'=>'و','إ'=>'ا','أ'=>'ا','آ'=>'ا','‌'=>' ']);$s=mb_strtolower($s,'UTF-8');$s=preg_replace('/[^0-9a-zآ-ی]+/u',' ',$s)??$s;return trim(preg_replace('/\s+/u',' ',$s)??$s);}function hasw(string $t,array $ws):bool{foreach($ws as $w)if(mb_strpos($t,$w,0,'UTF-8')!==false)return true;return false;}
$rules=[
