$known=array_merge(array_keys($rules),['سایر']);$rows=$pdo->query("SELECT id,name,brand,quantity_label,category FROM products WHERE active=1 ORDER BY id")->fetchAll();$upd=$pdo->prepare('UPDATE products SET category=?,updated_at=NOW() WHERE id=?');$counts=array_fill_keys($known,0);$changed=0;$pdo->beginTransaction();
foreach($rows as $r){$text=nz(implode(' ',[(string)($r['name']??''),(string)($r['brand']??''),(string)($r['quantity_label']??'')]));$cat='';foreach($rules as $name=>$words){if(hasw($text,$words)){$cat=$name;break;}}if($cat===''){$cur=trim((string)($r['category']??''));$cat=in_array($cur,$known,true)?$cur:'سایر';}$counts[$cat]++;if((string)($r['category']??'')!==$cat){$upd->execute([$cat,(int)$r['id']]);$changed++;}}
$pdo->commit();echo json_encode(['ok'=>true,'total'=>count($rows),'changed'=>$changed,'counts'=>$counts],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);
